def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string must consist only of decimal digits.
    """
    # Basic validation
    if not isinstance(num_str, str):
        raise TypeError("num_str must be a string")
    if not isinstance(N, int) or not isinstance(K, int):
        raise TypeError("N and K must be integers")
    if N != len(num_str):
        raise ValueError("N does not match the length of num_str")
    if K < 0 or K > N - 1:
        raise ValueError("K must be between 0 and N-1 inclusive")
    if not num_str.isdigit():
        raise ValueError("num_str must contain only digits")

    # Special cases
    if K == 0:
        return int(num_str)

    # Precompute integer values of all substrings to avoid repeated conversions
    substr_val = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        val = 0
        for j in range(i, N):
            val = val * 10 + (ord(num_str[j]) - 48)
            substr_val[i][j + 1] = val

    # dp[i][k] = maximum product for first i digits with k multiplications
    dp = [[-1] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # product of zero numbers is 1 (used as neutral element)

    for i in range(1, N + 1):
        # No multiplication: whole prefix as one number
        dp[i][0] = substr_val[0][i]
        max_k = min(K, i - 1)
        for k in range(1, max_k + 1):
            best = -1
            # last number starts at position j (0-indexed)
            # need at least k digits before j to have k-1 multiplications
            for j in range(k, i):
                prev = dp[j][k - 1]
                if prev == -1:
                    continue
                prod = prev * substr_val[j][i]
                if prod > best:
                    best = prod
            dp[i][k] = best

    result = dp[N][K]
    if result == -1:
        raise RuntimeError("Failed to compute maximum product")
    return result

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    # Validate inputs
    if not isinstance(grades, (list, tuple)) or len(grades) != 2:
        raise ValueError("grades must be a list of two integers")
    if not all(isinstance(g, int) for g in grades):
        raise ValueError("grades must contain integers")
    if leader not in ('Y', 'N'):
        raise ValueError("leader must be 'Y' or 'N'")
    if west not in ('Y', 'N'):
        raise ValueError("west must be 'Y' or 'N'")
    if not isinstance(papers, int) or papers < 0:
        raise ValueError("papers must be a non-negative integer")

    avg, class_eval = grades
    scholarship = 0

    # Rule 1
    if avg > 80 and papers >= 1:
        scholarship += 8000
    # Rule 2
    if avg > 85 and class_eval > 80:
        scholarship += 4000
    # Rule 3
    if avg > 90:
        scholarship += 2000
    # Rule 4
    if avg > 85 and west == 'Y':
        scholarship += 1000
    # Rule 5
    if class_eval > 80 and leader == 'Y':
        scholarship += 850

    return scholarship

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps or "NO ANSWER!" if impossible.
    """
    if A == B:
        return 0
    if not rules:
        return "NO ANSWER!"
    from collections import deque
    visited = {A}
    queue = deque([(A, 0)])
    max_depth = 10
    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return depth + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, depth + 1))
                start = idx + 1
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Basic type validation
    if not isinstance(scenario, str):
        raise TypeError("scenario must be a string")
    if not isinstance(liar_count, set):
        raise TypeError("liar_count must be a set")
    if not isinstance(statements, dict):
        raise TypeError("statements must be a dict")
    if not isinstance(days_of_week, set):
        raise TypeError("days_of_week must be a set")

    # Validate contents of sets and dict
    for name in liar_count:
        if not isinstance(name, str):
            raise ValueError("liar_count must contain strings only")
    for day in days_of_week:
        if not isinstance(day, str):
            raise ValueError("days_of_week must contain strings only")
    for participant, stmts in statements.items():
        if not isinstance(participant, str):
            raise ValueError("statements keys must be strings")
        if not isinstance(stmts, list):
            raise ValueError(f"statements for participant {participant} must be a list")
        for s in stmts:
            if not isinstance(s, str):
                raise ValueError(f"statement '{s}' for participant {participant} must be a string")

    # Helper to determine truth of a statement
    def evaluate_statement(participant: str, stmt: str) -> bool:
        # Skip statements about days of the week
        for day in days_of_week:
            if day in stmt:
                return None  # indicates to skip

        # Clean punctuation
        cleaned = stmt.strip().rstrip('.').strip()
        tokens = cleaned.split()
        if not tokens:
            return None

        # Determine subject
        if tokens[0] == "I":
            subject = participant
        else:
            subject = tokens[0]

        # Determine if statement is about guilt
        if len(tokens) >= 3 and tokens[1] in ("am", "is"):
            if tokens[2] == "guilty":
                guilty = True
            elif len(tokens) >= 4 and tokens[2] == "not" and tokens[3] == "guilty":
                guilty = False
            else:
                return None  # unrecognized pattern
        else:
            return None  # unrecognized pattern

        # Evaluate truth
        if guilty:
            return subject == scenario
        else:
            return subject != scenario

    # Iterate over all statements
    for participant, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate_statement(participant, stmt)
            if truth is None:
                continue  # skip this statement
            is_liar = participant in liar_count
            if is_liar and truth:
                return False  # liar told truth
            if not is_liar and not truth:
                return False  # truth-teller lied

    return True

